-- 나정걸 교수 주요 논문 교체 (2026-11-18): 기존 '주요 논문' 목록을 받은 5편으로 바꾼다. 다른 항목은 그대로 둔다.
-- 여러 번 실행해도 결과가 같다.
update faculty set
  bio_ko = regexp_replace(bio_ko, '<h3>주요 논문</h3>\s*<ul>.*?</ul>', $q$<h3>주요 논문</h3><ul><li>Byoung Hoon Park, Kyutae Jung, Jungyoon Shin, Yongjoon Cho, Yoonjae Kim, J. Lee, Jeong-Geol Na, "Model-Informed Kinetic Synchronization for Intensified Methane-to-Poly(3-hydroxybutyrate) Bioconversion," <em>ACS Sustainable Chemistry &amp; Engineering</em> (2026) <a href="https://doi.org/10.1021/acssuschemeng.6c05527">doi.org/10.1021/acssuschemeng.6c05527</a></li><li>Taehwan Kim, Jang-Seob Lee, Jinwon Lee, Yong Hwan Kim, Jeong-Geol Na, Byung-Keun Oh, "Intercellular whole-cell cascade strategy for robust CO-to-formate bioconversion," <em>Bioresource Technology</em> (2026) <a href="https://doi.org/10.1016/j.biortech.2026.135310">doi.org/10.1016/j.biortech.2026.135310</a></li><li>Sukjae Han, Joon Young Park, Yong Hee Han, Ina Bang, Hyeonwoo Mun, Ok Kyung Lee, Ji Sung Hyung, Jeong-Geol Na, Eun Yeol Lee, Donghyuk Kim, Sang Woo Seo, "Genome-wide regulon of NtrC reveals genetic regulation under nitrogen limitation in <em>Methylomonas</em> sp. DH-1," <em>iScience</em> (2026) <a href="https://doi.org/10.1016/j.isci.2025.114322">doi.org/10.1016/j.isci.2025.114322</a></li><li>Seong-Hoon Jun, Jeongwoo Lee, Dayoun Kim, Jinwon Lee, B. Oh, Jeong-Geol Na, "Demand-driven dual carbon delivery strategy for maximizing CO₂ utilization in poly(3-hydroxybutyrate) biosynthesis by <em>Cupriavidus necator</em> H16," <em>Journal of CO₂ Utilization</em> (2026) <a href="https://doi.org/10.1016/j.jcou.2026.103575">doi.org/10.1016/j.jcou.2026.103575</a></li><li>Eungsu Kang, Hyo Jin Hong, Hyeon Bang Noh, J. Hyung, Jae-Hwan Jo, Jeong-Ho Park, Min-Sik Kim, Jeong-Geol Na, Y. Choi, "Bionanofluids enhance methane bioconversion and reshape time-resolved methanotroph physiology," <em>Journal of Biological Engineering</em> (2026) <a href="https://doi.org/10.1186/s13036-026-00761-7">doi.org/10.1186/s13036-026-00761-7</a></li></ul>$q$),
  bio_en = regexp_replace(bio_en, '<h3>Selected Publications</h3>\s*<ul>.*?</ul>', $q$<h3>Selected Publications</h3><ul><li>Byoung Hoon Park, Kyutae Jung, Jungyoon Shin, Yongjoon Cho, Yoonjae Kim, J. Lee, Jeong-Geol Na, "Model-Informed Kinetic Synchronization for Intensified Methane-to-Poly(3-hydroxybutyrate) Bioconversion," <em>ACS Sustainable Chemistry &amp; Engineering</em> (2026) <a href="https://doi.org/10.1021/acssuschemeng.6c05527">doi.org/10.1021/acssuschemeng.6c05527</a></li><li>Taehwan Kim, Jang-Seob Lee, Jinwon Lee, Yong Hwan Kim, Jeong-Geol Na, Byung-Keun Oh, "Intercellular whole-cell cascade strategy for robust CO-to-formate bioconversion," <em>Bioresource Technology</em> (2026) <a href="https://doi.org/10.1016/j.biortech.2026.135310">doi.org/10.1016/j.biortech.2026.135310</a></li><li>Sukjae Han, Joon Young Park, Yong Hee Han, Ina Bang, Hyeonwoo Mun, Ok Kyung Lee, Ji Sung Hyung, Jeong-Geol Na, Eun Yeol Lee, Donghyuk Kim, Sang Woo Seo, "Genome-wide regulon of NtrC reveals genetic regulation under nitrogen limitation in <em>Methylomonas</em> sp. DH-1," <em>iScience</em> (2026) <a href="https://doi.org/10.1016/j.isci.2025.114322">doi.org/10.1016/j.isci.2025.114322</a></li><li>Seong-Hoon Jun, Jeongwoo Lee, Dayoun Kim, Jinwon Lee, B. Oh, Jeong-Geol Na, "Demand-driven dual carbon delivery strategy for maximizing CO₂ utilization in poly(3-hydroxybutyrate) biosynthesis by <em>Cupriavidus necator</em> H16," <em>Journal of CO₂ Utilization</em> (2026) <a href="https://doi.org/10.1016/j.jcou.2026.103575">doi.org/10.1016/j.jcou.2026.103575</a></li><li>Eungsu Kang, Hyo Jin Hong, Hyeon Bang Noh, J. Hyung, Jae-Hwan Jo, Jeong-Ho Park, Min-Sik Kim, Jeong-Geol Na, Y. Choi, "Bionanofluids enhance methane bioconversion and reshape time-resolved methanotroph physiology," <em>Journal of Biological Engineering</em> (2026) <a href="https://doi.org/10.1186/s13036-026-00761-7">doi.org/10.1186/s13036-026-00761-7</a></li></ul>$q$)
where name_ko = '나정걸';

-- 두 칸 모두 true 이면 정상
select name_ko, bio_ko like '%acssuschemeng.6c05527%' as ko_ok, bio_en like '%acssuschemeng.6c05527%' as en_ok
from faculty where name_ko = '나정걸';
